CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS locations (id INT AUTO_INCREMENT PRIMARY KEY,building VARCHAR(100) NOT NULL,floor VARCHAR(30) NOT NULL,room VARCHAR(80) NOT NULL, UNIQUE KEY uniq_loc(building,floor,room));
CREATE TABLE IF NOT EXISTS issues (id INT AUTO_INCREMENT PRIMARY KEY,reporter_id INT NOT NULL,location_id INT NOT NULL,category ENUM('Electrical','Cleaning','IT','Water','Furniture','Other') NOT NULL,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,severity TINYINT NOT NULL DEFAULT 2,impact TINYINT NOT NULL DEFAULT 2,status ENUM('submitted','assigned','in_progress','resolved','reopened') NOT NULL DEFAULT 'submitted',assigned_to INT NULL,resolution_notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,resolved_at TIMESTAMP NULL,FOREIGN KEY (reporter_id) REFERENCES users(id),FOREIGN KEY(location_id) REFERENCES locations(id),FOREIGN KEY(assigned_to) REFERENCES users(id),INDEX idx_status(status),INDEX idx_location(location_id));
CREATE TABLE IF NOT EXISTS confirmations (issue_id INT NOT NULL,user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(issue_id,user_id),FOREIGN KEY(issue_id) REFERENCES issues(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS status_history (id INT AUTO_INCREMENT PRIMARY KEY,issue_id INT NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,changed_by INT NOT NULL,note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(issue_id) REFERENCES issues(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id));
